import {escapeHtml as e} from './inventory.mjs';
import {bytes} from './usage.mjs';
const record=value=>{if(!value||typeof value!=='object'||Array.isArray(value))throw new Error('NAS 規格格式錯誤');return value;};
const text=value=>{if(value==null)return '';if(typeof value!=='string')throw new Error('NAS 文字欄位格式錯誤');return value.slice(0,1500);};
export function normalizeNas(value){if(value==null)return null;record(value);if(value.arrays!=null&&(!Array.isArray(value.arrays)||value.arrays.length>128))throw new Error('NAS 陣列格式錯誤');return {model:text(value.model),firmwareVersion:text(value.firmwareVersion),firmwareBuild:text(value.firmwareBuild),kernel:text(value.kernel),arrays:(value.arrays??[]).map(x=>{record(x);if(x.sizeBytes!=null&&(typeof x.sizeBytes!=='number'||!Number.isFinite(x.sizeBytes)||x.sizeBytes<0))throw new Error('NAS 陣列容量格式錯誤');if(x.members!=null&&(!Array.isArray(x.members)||x.members.length>256))throw new Error('NAS 成員格式錯誤');return {name:text(x.name),level:text(x.level),state:text(x.state),members:(x.members??[]).map(text),sizeBytes:x.sizeBytes??null};})};}
export function nasSummary(pc){if(!pc.nas)return '';const data=pc.nas.arrays.slice().sort((a,b)=>(b.sizeBytes??0)-(a.sizeBytes??0))[0];return `<section class="ai-summary"><div><strong>QNAP ${e(pc.nas.model)}</strong><p>QTS ${e(pc.nas.firmwareVersion)} · ${e(data?.level.toUpperCase()||'RAID 未取得')} · 最大陣列 ${e(bytes(data?.sizeBytes))}</p></div><button class="button" data-tab="storage">查看儲存配置 →</button></section>`;}
export function nasStorageInfo(pc,snapshot){if(!pc.nas)return '';const arrays=pc.nas.arrays.slice().sort((a,b)=>(b.sizeBytes??0)-(a.sizeBytes??0)),media=pc.hardware.disks.filter(x=>x.mediaType!=='eMMC'),raw=media.reduce((sum,x)=>sum+(x.sizeGB??0)*1024**3,0),largestVolume=snapshot.volumes.slice().sort((a,b)=>(b.sizeBytes??0)-(a.sizeBytes??0))[0];return `<section class="nas-storage"><div class="block-heading"><h3>NAS 硬碟與 RAID 配置</h3><small>QNAP ${e(pc.nas.model)}</small></div><div class="usage-metrics">${[['資料硬碟原始總量',bytes(raw)],['最大 RAID 陣列容量',bytes(arrays[0]?.sizeBytes)],['最大已掛載磁碟區',bytes(largestVolume?.sizeBytes)]].map(([label,value])=>`<div><small>${label}</small><strong>${e(value)}</strong></div>`).join('')}</div><details class="usage-branch"><summary><span class="branch-title">RAID 陣列明細</span><span class="usage-count">${arrays.length} 個（含系統陣列）</span></summary><div class="branch-content"><div class="resource-scroll"><table class="resource-table"><thead><tr><th>陣列 / 類型</th><th>成員</th><th>容量</th><th>Kernel 狀態</th></tr></thead><tbody>${arrays.map(a=>`<tr><td>${e(a.name)} · ${e(a.level.toUpperCase())}</td><td>${e(a.members.join(' / '))}</td><td>${e(bytes(a.sizeBytes))}</td><td>${e(a.state||'未取得')}</td></tr>`).join('')}</tbody></table></div></div></details><p class="usage-note">硬碟原始總量不含 eMMC 開機快閃記憶體。RAID 陣列容量、已掛載磁碟區與檔案使用量分開列示；鏡像硬碟不會重複計入「已用儲存」。RAID 配置為最近盤點資料。</p></section>`;}
